"""Builds dispatch-copilot.json, the storyline spec for the Brightwork Dispatch Copilot deck."""
import json, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
PACK = (ROOT / "evidence" / "briefing-pack.md").read_text()

DP = []
def u(id, slide, label, value, unit, excerpt, locator, period=None, used_in=None, **kw):
    assert excerpt in PACK, f"excerpt not verbatim: {excerpt}"
    d = {"id": id, "slide_id": slide, "label": label, "value": value, "unit": unit, "source_id": "s1",
         "excerpt": excerpt, "locator": locator}
    if period: d["period"] = period
    if used_in: d["used_in"] = used_in
    d.update(kw); DP.append(d)
def dv(id, slide, label, value, unit, derived_from, calc, formula, period=None, used_in=None, assumptions=None):
    d = {"id": id, "slide_id": slide, "label": label, "value": value, "unit": unit, "source_id": "s2",
         "derived_from": derived_from, "calc": calc, "formula": formula}
    if period: d["period"] = period
    if used_in: d["used_in"] = used_in
    if assumptions:
        d["estimate"] = True; d["assumptions"] = assumptions
    DP.append(d)
P = lambda r: {"data_ref": r}

